@js:
(function(){
  var u = String(baseUrl || ''), html = String(result || '');
  var m = u.match(/^(https?:\/\/[^/]+)(\/index\/\d+\/\d+\/)(\d+)(\.html\/?)$/);
  if(!m) return null;
  var tm = html.match(/共(\d+)章/);
  if(!tm) return null;
  var total = parseInt(tm[1], 10);
  var rm = html.match(/章節目錄\s*\((\d+)-(\d+)\)/);
  var per = rm ? (parseInt(rm[2],10) - parseInt(rm[1],10) + 1) : 100;
  var pg = parseInt(m[3], 10);
  if(pg * per >= total) return null;
  return m[1] + m[2] + (pg + 1) + m[4];
})()

